public class CanteenInventory{static class Item{String itemName;int stock;Item(String n,int s){this.itemName=n;this.stock=s;}void restock(int s){this.stock+=s;}}public static void main(String[] z){Item[] a={new Item("Samosa",15),new Item("Tea Powder",40),new Item("Bread",8),new Item("Biscuit Packs",25)};for(Item x:a){x.restock(20);System.out.println(x.itemName+" | Final Stock: "+x.stock);}}}